// Rebuild the portable artwork after editing the original WebP files.
const fs = require("node:fs");
const path = require("node:path");
function packTextures() {
  const dir = path.join(__dirname, "dist", "city", "textures");
  const data = {};
  for (const name of ["facade", "upper", "retail", "face"]) {
    data[name] = fs.readFileSync(path.join(dir, name + ".webp")).toString("base64");
  }
  fs.writeFileSync(path.join(dir, "atlas-data.js"),
    "// Generated by pack-textures.cjs from the original WebP artwork.\n" +
    "window.C72AtlasData = " + JSON.stringify(data, null, 2) + ";\n");
}
if (require.main === module) packTextures();
module.exports = packTextures;
